-- Granite cluster schedule for 22-29 August 2026.
-- Generated from the reviewed Markdown source files. Safe to rerun.

BEGIN;

-- The previous health slug was scheduled but never public. Keep references canonical.
UPDATE blog_translations
SET content_html = replace(
      replace(content_html,
        'data-pending-blog-link="granite-advantages-disadvantages-health"',
        'data-pending-blog-link="granite-advantages-disadvantages"'
      ),
      '/fa/blogs/granite-advantages-disadvantages-health',
      '/fa/blogs/granite-advantages-disadvantages'
    ),
    content_json = '{"type":"doc","content":[]}'::jsonb,
    updated_at = NOW()
WHERE content_html LIKE '%granite-advantages-disadvantages-health%';

CREATE OR REPLACE FUNCTION pg_temp.upsert_scheduled_fa_blog(
  p_aliases TEXT[],
  p_slug TEXT,
  p_title TEXT,
  p_excerpt TEXT,
  p_seo_title TEXT,
  p_seo_description TEXT,
  p_scheduled_at TIMESTAMPTZ,
  p_tags TEXT[],
  p_content_html TEXT
) RETURNS VOID LANGUAGE plpgsql AS $function$
DECLARE
  target_blog_id INTEGER;
  is_already_public BOOLEAN := FALSE;
BEGIN
  SELECT bt.blog_id,
         b.status = 'published' AND COALESCE(b.published_at, b.created_at) <= NOW()
  INTO target_blog_id, is_already_public
  FROM blog_translations bt
  JOIN blogs b ON b.id = bt.blog_id
  WHERE bt.locale = 'fa' AND bt.slug = ANY(p_aliases)
  ORDER BY (bt.slug = p_slug) DESC
  LIMIT 1;

  IF target_blog_id IS NULL THEN
    INSERT INTO blogs (
      title, excerpt, content, status, author_name, category_slug, tags,
      is_featured, scheduled_at, published_at, created_at, updated_at
    ) VALUES (
      p_title, p_excerpt, '', 'scheduled', 'تیم محتوای سنگ حسن', 'guide', p_tags,
      FALSE, p_scheduled_at, NULL, NOW(), NOW()
    ) RETURNING id INTO target_blog_id;
  ELSE
    UPDATE blogs
    SET title = p_title,
        excerpt = p_excerpt,
        status = CASE WHEN is_already_public THEN 'published' ELSE 'scheduled' END,
        author_name = 'تیم محتوای سنگ حسن',
        category_slug = 'guide',
        tags = p_tags,
        scheduled_at = CASE WHEN is_already_public THEN NULL ELSE p_scheduled_at END,
        published_at = CASE WHEN is_already_public THEN published_at ELSE NULL END,
        updated_at = NOW()
    WHERE id = target_blog_id;
  END IF;

  INSERT INTO blog_translations (
    blog_id, locale, title, slug, excerpt, content_json, content_html,
    seo_title, seo_description, canonical_url, robots, translation_status,
    featured_image_alt, og_image_alt, created_at, updated_at
  ) VALUES (
    target_blog_id, 'fa', p_title, p_slug, p_excerpt,
    '{"type":"doc","content":[]}'::jsonb, p_content_html,
    p_seo_title, p_seo_description, '/fa/blogs/' || p_slug,
    'index,follow', 'published', '', '', NOW(), NOW()
  )
  ON CONFLICT (blog_id, locale) DO UPDATE SET
    title = EXCLUDED.title,
    slug = EXCLUDED.slug,
    excerpt = EXCLUDED.excerpt,
    content_json = EXCLUDED.content_json,
    content_html = EXCLUDED.content_html,
    seo_title = EXCLUDED.seo_title,
    seo_description = EXCLUDED.seo_description,
    canonical_url = EXCLUDED.canonical_url,
    robots = EXCLUDED.robots,
    translation_status = EXCLUDED.translation_status,
    featured_image_alt = CASE
      WHEN COALESCE(blog_translations.featured_image_alt, '') <> '' THEN blog_translations.featured_image_alt
      ELSE EXCLUDED.featured_image_alt
    END,
    og_image_alt = CASE
      WHEN COALESCE(blog_translations.og_image_alt, '') <> '' THEN blog_translations.og_image_alt
      ELSE EXCLUDED.og_image_alt
    END,
    updated_at = NOW();
END
$function$;

