  $content_granite_slab_guide$<div data-content-version="granite-cluster-2026"><p><strong>اسلب گرانیت</strong> یکی از شکل‌های مهم عرضه سنگ گرانیت در پروژه‌های ساختمانی و معماری است. وقتی قرار است سطحی بزرگ با بند کمتر، ظاهر یکپارچه‌تر و نمای طبیعی‌تر سنگ اجرا شود، معمولاً استفاده از اسلب نسبت به قطعات کوچک‌تر جذاب‌تر است.</p>
<p>اسلب گرانیت می‌تواند در بخش‌هایی مانند:</p>
<ul>
<li>صفحه کابینت</li>
<li>جزیره آشپزخانه</li>
<li>کانتر</li>
<li>کف لابی</li>
<li>دیوار شاخص</li>
<li>میز</li>
<li>فضای تجاری</li>
<li>بعضی پروژه‌های نمای ساختمان</li>
</ul>
<p>استفاده شود.</p>
<p>اما خرید اسلب فقط انتخاب یک رنگ زیبا نیست.</p>
<p>در یک اسلب گرانیت باید مواردی مانند:</p>
<ul>
<li>ابعاد واقعی</li>
<li>ضخامت</li>
<li>سلامت سنگ</li>
<li>ترک‌ها</li>
<li>سورت</li>
<li>کیفیت ساب</li>
<li>نوع فرآوری</li>
<li>تاب سنگ</li>
<li>محل برش</li>
<li>میزان پرت</li>
</ul>
<p>بررسی شوند.</p>
<p>گاهی یک اسلب از نظر ظاهری فوق‌العاده است، اما به دلیل ابعاد یا محل ترک برای پروژه موردنظر انتخاب مناسبی نیست.</p>
<p>در این مقاله بررسی می‌کنیم <strong>اسلب گرانیت چیست، چگونه تولید می‌شود، چه ابعادی دارد، چه کاربردهایی دارد و هنگام خرید باید دقیقاً به چه چیزهایی توجه کرد.</strong></p>
<hr>
<h2>اسلب گرانیت چیست؟</h2>
<p>در صنعت سنگ، <strong>اسلب</strong> به ورق نسبتاً بزرگ سنگ طبیعی گفته می‌شود که از یک بلوک یا کوپ استخراج‌شده از معدن برش داده می‌شود.</p>
<p>فرآیند ساده‌شده به این شکل است:</p>
<p><strong>معدن → استخراج بلوک → انتقال به کارخانه → برش بلوک → تولید اسلب → فرآوری سطح → سورت → برش پروژه</strong></p>
<p>بلوک گرانیت ابتدا از معدن استخراج می‌شود.</p>
<p>بعد وارد کارخانه می‌شود و با تجهیزات برش به صفحات بزرگ تبدیل می‌شود.</p>
<p>این صفحات قبل از اینکه به ابعاد نهایی پروژه برش بخورند، همان <strong>اسلب گرانیت</strong> هستند.</p>
<p>اگر می‌خواهید ابتدا با خود گرانیت، انواع آن، رنگ‌ها و معادن اصلی آشنا شوید:</p>
<p><a href="/fa/blogs/everything-about-granite-stone">سنگ گرانیت چیست؟ راهنمای کامل انواع و کاربردها</a></p>
<hr>
<h2>تفاوت اسلب گرانیت با تایل چیست؟</h2>
<p>تفاوت اصلی در <strong>ابعاد و نوع استفاده</strong> است.</p>
<h3>تایل گرانیت</h3>
<p>تایل معمولاً در ابعاد استاندارد یا کوچک‌تر تولید می‌شود.</p>
<p>مثلاً برای:</p>
<ul>
<li>کف</li>
<li>راهرو</li>
<li>دیوار</li>
<li>پروژه‌های متراژ بالا</li>
</ul>
<p>می‌توان از تایل استفاده کرد.</p>
<p>مزیت‌های تایل:</p>
<ul>
<li>حمل ساده‌تر</li>
<li>نصب ساده‌تر</li>
<li>امکان تعویض یک قطعه</li>
<li>مناسب پروژه‌های تکرارشونده</li>
<li>کنترل بهتر هزینه در بعضی پروژه‌ها</li>
</ul>
<hr>
<h3>اسلب گرانیت</h3>
<p>اسلب ابعاد بسیار بزرگ‌تری دارد.</p>
<p>مزیت اصلی آن:</p>
<ul>
<li>بند کمتر</li>
<li>نمایش بهتر طرح طبیعی</li>
<li>اجرای سطح بزرگ‌تر</li>
<li>امکان انتخاب محل دقیق برش</li>
<li>ظاهر لوکس‌تر</li>
</ul>
<p>است.</p>
<p>مثلاً برای یک <strong>جزیره آشپزخانه</strong>، استفاده از یک اسلب بزرگ معمولاً نتیجه بسیار زیباتری نسبت به چند قطعه کوچک ایجاد می‌کند.</p>
<hr>
<h2>اسلب گرانیت چگونه تولید می‌شود؟</h2>
<p>تولید اسلب با کیفیت از معدن شروع می‌شود.</p>
<hr>
<h3>مرحله اول: استخراج بلوک</h3>
<p>گرانیت باید به صورت بلوک نسبتاً سالم از معدن استخراج شود.</p>
<p>هرچه بلوک:</p>
<ul>
<li>بزرگ‌تر</li>
<li>سالم‌تر</li>
<li>کم‌ترک‌تر</li>
</ul>
<p>باشد، امکان تولید اسلب‌های بزرگ‌تر بیشتر است.</p>
<hr>
<h3>مرحله دوم: انتقال بلوک به کارخانه</h3>
<p>بلوک گرانیت وزن بسیار زیادی دارد.</p>
<p>به همین دلیل حمل بلوک نیازمند تجهیزات مناسب است.</p>
<p>در این مرحله سلامت بلوک باید حفظ شود تا ترک جدید ایجاد نشود.</p>
<hr>
<h3>مرحله سوم: برش بلوک</h3>
<p>بلوک به صفحات با ضخامت مشخص برش داده می‌شود.</p>
<p>در این مرحله عواملی مانند:</p>
<ul>
<li>دستگاه</li>
<li>دقت برش</li>
<li>ضخامت هدف</li>
<li>جهت برش</li>
</ul>
<p>روی کیفیت اسلب تأثیر دارند.</p>
<hr>
<h3>مرحله چهارم: بررسی سلامت اسلب</h3>
<p>بعد از برش، سطح اسلب بررسی می‌شود.</p>
<p>مواردی مانند:</p>
<ul>
<li>ترک</li>
<li>شکستگی</li>
<li>رگه</li>
<li>نقاط ضعیف</li>
<li>تغییرات رنگ</li>
</ul>
<p>مشخص می‌شوند.</p>
<hr>
<h3>مرحله پنجم: تقویت در صورت نیاز</h3>
<p>بسته به ساختار سنگ، ممکن است از:</p>
<ul>
<li>رزین</li>
