<li>مش</li>
</ul>
<p>استفاده شود.</p>
<p>وجود این موارد الزاماً نشانه کیفیت پایین نیست.</p>
<p>مهم این است که بدانیم:</p>
<blockquote>
<p>آیا تقویت به صورت اصولی و برای افزایش پایداری سنگ انجام شده یا برای پوشاندن ضعف شدید سنگ؟</p>
</blockquote>
<hr>
<h3>مرحله ششم: فرآوری سطح</h3>
<p>سطح اسلب می‌تواند به صورت‌های مختلف فرآوری شود.</p>
<p>مثلاً:</p>
