<hr>
<h2>محل سینک در اسلب گرانیت</h2>
<p>یکی از حساس‌ترین نقاط کانتر همین بخش است.</p>
<p>وقتی محل سینک بریده می‌شود، بخش‌هایی از سنگ باریک می‌شوند.</p>
