<li>دهانه آزاد</li>
<li>ضخامت</li>
<li>محل اتصال</li>
</ul>
<p>بررسی شود.</p>
<hr>
<h2>اسلب گرانیت برای فضای بیرونی</h2>
<p>گرانیت از نظر مقاومت می‌تواند برای فضای بیرونی گزینه مناسبی باشد.</p>
<p>اما سطح اسلب اهمیت زیادی دارد.</p>
<p>اگر قرار است روی کف فضای بیرونی استفاده شود، سطح صیقلی ممکن است لغزنده باشد.</p>
<p>در چنین شرایطی می‌توان فرآوری‌هایی مانند:</p>
<ul>
<li>فلیم</li>
<li>بوش‌همر</li>
<li>سندبلاست</li>
</ul>
<p>را بررسی کرد.</p>
<hr>
<h2>آیا اسلب گرانیت برای نما مناسب است؟</h2>
<p>بله، اما با یک شرط بسیار مهم:</p>
<p><strong>سیستم نصب باید مهندسی باشد.</strong></p>
<p>اسلب بزرگ:</p>
<ul>
<li>وزن بالا</li>
<li>سطح زیاد</li>
<li>نیروی بیشتر روی اتصال</li>
</ul>
<p>دارد.</p>
<p>بنابراین نمی‌توان برای نمای خارجی بزرگ فقط به ملات اعتماد کرد.</p>
