<li>طبیعی‌تر</li>
</ul>
<p>است.</p>
<p>برای:</p>
<ul>
<li>کانتر</li>
<li>میز</li>
<li>دیوار داخلی</li>
</ul>
<p>می‌تواند بسیار جذاب باشد.</p>
