<h3>اسلب گرانیت فلیم</h3>
<p>سطح زبرتر است.</p>
<p>برای:</p>
<ul>
<li>فضای بیرونی</li>
<li>نما</li>
<li>محوطه</li>
</ul>
<p>قابل استفاده است.</p>
<hr>
<h2>اسلب گرانیت Bookmatch چیست؟</h2>
<p>Bookmatch زمانی اتفاق می‌افتد که دو اسلب کنار هم به شکلی نصب شوند که طرح آنها حالت آینه‌ای ایجاد کند.</p>
<p>این تکنیک در سنگ‌های دارای:</p>
<ul>
<li>رگه واضح</li>
<li>حرکت</li>
<li>خطوط خاص</li>
</ul>
<p>اثر بیشتری دارد.</p>
<p>در بسیاری از گرانیت‌های دانه‌دار ساده، Bookmatch چندان چشمگیر نیست.</p>
<p>اما بعضی گرانیت‌های خاص می‌توانند نتیجه بسیار خوبی داشته باشند.</p>
<hr>
<h2>آیا همه گرانیت‌ها برای Bookmatch مناسب‌اند؟</h2>
<p>نه.</p>
<p>اگر طرح سنگ یکنواخت باشد، تفاوت زیادی ایجاد نمی‌شود.</p>
<p>قبل از تصمیم باید:</p>
<ul>
<li>ترتیب اسلب‌ها</li>
