<li>دانه‌بندی</li>
<li>سلامت</li>
<li>تغییرات طبیعی</li>
<li>کیفیت ظاهری</li>
</ul>
<p>گفته می‌شود.</p>
<p>اگر چند اسلب قرار است کنار هم استفاده شوند، هماهنگی سورت بسیار مهم است.</p>
