<hr>
<h2>چرا دو اسلب از یک گرانیت با هم فرق دارند؟</h2>
<p>چون سنگ طبیعی محصول چاپ‌شده نیست.</p>
<p>حتی دو اسلب از یک بلوک ممکن است کمی تفاوت داشته باشند.</p>
<p>تغییرات می‌تواند شامل:</p>
<ul>
