<li>رگه طبیعی</li>
</ul>
<p>باشند.</p>
<p>اما ترک واقعی باید جدی گرفته شود.</p>
<p>خصوصاً اگر قرار است اسلب برای:</p>
<ul>
<li>کانتر</li>
<li>قطعات باریک</li>
<li>میز</li>
