<hr>
<h2>رزین در اسلب گرانیت</h2>
<p>وجود رزین همیشه نشانه بد بودن سنگ نیست.</p>
<p>رزین می‌تواند برای:</p>
<ul>
<li>پر کردن نقاط ریز</li>
<li>تقویت سطح</li>
<li>افزایش کیفیت فرآوری</li>
</ul>
<p>استفاده شود.</p>
<p>مهم این است که مقدار آن منطقی و اجرای آن باکیفیت باشد.</p>
<hr>
<h2>پشت مش اسلب چیست؟</h2>
<p>در بعضی اسلب‌ها برای افزایش پایداری در حمل و فرآوری، پشت سنگ مش نصب می‌شود.</p>
<p>این کار مخصوصاً در سنگ‌هایی که:</p>
<ul>
<li>رگه</li>
<li>ترک طبیعی</li>
<li>ساختار حساس‌تر</li>
</ul>
<p>دارند دیده می‌شود.</p>
<p>در گرانیت‌های بسیار متراکم و سالم ممکن است نیاز کمتری به مش وجود داشته باشد.</p>
<hr>
<h2>تاب اسلب چیست؟</h2>
<p>گاهی اسلب کاملاً تخت نیست و کمی انحنا دارد.</p>
<p>این مسئله در نصب:</p>
<ul>
<li>کف</li>
<li>کانتر</li>
<li>دیوار</li>
</ul>
<p>می‌تواند مشکل ایجاد کند.</p>
<p>برای بررسی، بهتر است اسلب از زاویه مناسب دیده شود یا با ابزار کنترل شود.</p>
<hr>
<h2>کیفیت ساب اسلب</h2>
<p>ساب خوب باید:</p>
<ul>
<li>یکنواخت</li>
<li>بدون موج محسوس</li>
<li>بدون مناطق مات پراکنده</li>
</ul>
<p>باشد.</p>
<p>یک روش ساده بررسی:</p>
<blockquote>
<p>سطح را از زاویه مایل در نور نگاه کنید.</p>
</blockquote>
<p>اگر انعکاس نور شکسته و موج‌دار باشد، کیفیت سطح ممکن است پایین باشد.</p>
<hr>
<h2>لبه‌های اسلب</h2>
<p>لبه‌ها باید از نظر:</p>
<ul>
<li>شکستگی</li>
<li>لب‌پریدگی</li>
<li>ترک</li>
</ul>
<p>بررسی شوند.</p>
<p>در بعضی پروژه‌ها چند سانتی‌متر از لبه قابل استفاده نیست و این مسئله باید در محاسبه ابعاد واقعی لحاظ شود.</p>
<hr>
<h2>قیمت اسلب گرانیت به چه عواملی بستگی دارد؟</h2>
<p>قیمت اسلب به عوامل مختلفی وابسته است.</p>
<hr>
<h3>نوع گرانیت</h3>
<p>معدن و نوع سنگ اهمیت زیادی دارد.</p>
<hr>
<h3>رنگ</h3>
<p>رنگ‌های خاص مانند:</p>
<ul>
<li>سبز</li>
<li>مشکی خاص</li>
<li>قرمز</li>
</ul>
<p>می‌توانند قیمت بیشتری داشته باشند.</p>
<hr>
<h3>سورت</h3>
<p>اسلب یکدست‌تر و سالم‌تر معمولاً ارزش بیشتری دارد.</p>
<hr>
<h3>ابعاد</h3>
<p>اسلب بزرگ و سالم معمولاً کمیاب‌تر است.</p>
<hr>
<h3>ضخامت</h3>
<p>ضخامت بیشتر هزینه را افزایش می‌دهد.</p>
