<li>چرمی</li>
<li>فلیم</li>
<li>هون‌شده</li>
</ul>
<p>می‌تواند قیمت متفاوتی داشته باشد.</p>
<hr>
<h3>سلامت</h3>
<p>وجود ترک یا شکستگی روی قیمت تأثیر دارد.</p>
<hr>
<h2>آیا قیمت اسلب را متری حساب می‌کنند؟</h2>
<p>اغلب قیمت بر اساس مساحت اعلام می‌شود.</p>
<p>اما برای پروژه واقعی، فقط قیمت هر متر کافی نیست.</p>
<p>مثلاً ممکن است برای یک کانتر 5 مترمربع سطح نهایی داشته باشید اما به دلیل ابعاد و نقشه برش مجبور شوید 7 متر اسلب تهیه کنید.</p>
<p>بنابراین:</p>
<blockquote>
<p><strong>هزینه واقعی = سطح خریداری‌شده + پرت + برش + حمل + نصب</strong></p>
</blockquote>
<hr>
<h2>پرت اسلب چیست؟</h2>
<p>بخش‌هایی از اسلب بعد از برش ممکن است دیگر برای پروژه اصلی قابل استفاده نباشند.</p>
<p>به این مقدار پرت گفته می‌شود.</p>
<p>مثلاً در یک کانتر:</p>
<ul>
<li>محل سینک</li>
<li>محل اجاق</li>
<li>فرم L</li>
<li>ستون</li>
</ul>
<p>می‌توانند پرت ایجاد کنند.</p>
<hr>
<h2>چگونه پرت اسلب را کم کنیم؟</h2>
<p>با:</p>
<ul>
<li>نقشه دقیق</li>
<li>انتخاب ابعاد مناسب اسلب</li>
<li>چیدمان برش</li>
<li>استفاده از باقیمانده‌ها برای بخش‌های کوچک‌تر</li>
</ul>
<p>می‌توان هزینه را کاهش داد.</p>
<hr>
<h2>نقشه برش اسلب چیست؟</h2>
<p>قبل از برش، ابعاد قطعات نهایی روی تصویر یا خود اسلب جانمایی می‌شوند.</p>
<p>هدف:</p>
<ul>
<li>کنترل رگه</li>
<li>کاهش پرت</li>
<li>دوری از ترک</li>
<li>تعیین محل اتصال</li>
</ul>
<p>است.</p>
<p>این مرحله برای پروژه‌های:</p>
<ul>
<li>کانتر</li>
<li>جزیره</li>
<li>دیوار شاخص</li>
</ul>
<p>بسیار مهم است.</p>
<hr>
<h2>خرید اسلب فقط از روی عکس درست است؟</h2>
<p>برای انتخاب اولیه، عکس مفید است.</p>
<p>اما نمی‌تواند همه چیز را نشان دهد.</p>
<p>مثلاً:</p>
<ul>
