<li>ترک ریز</li>
<li>کیفیت ساب</li>
<li>عمق واقعی رنگ</li>
<li>بافت سطح</li>
</ul>
<p>در عکس ممکن است مشخص نباشد.</p>
<p>اگر پروژه مهم است، بررسی دقیق‌تر اسلب توصیه می‌شود.</p>
<hr>
<h2>چرا رنگ اسلب در عکس متفاوت دیده می‌شود؟</h2>
<p>عوامل مختلفی تأثیر دارند:</p>
<ul>
<li>نور</li>
<li>دوربین</li>
<li>صفحه نمایش</li>
<li>پردازش عکس</li>
<li>محیط</li>
</ul>
<p>به همین دلیل عکس را باید برای انتخاب اولیه استفاده کرد، نه تأیید نهایی رنگ.</p>
<hr>
<h2>اسلب گرانیت ایرانی</h2>
<p>ایران گرانیت‌های متنوعی دارد.</p>
<p>نمونه‌هایی از مناطق مختلف مانند:</p>
<ul>
