<li>نطنز</li>
<li>نهبندان</li>
<li>زاهدان</li>
<li>بیرجند</li>
</ul>
<p>در پروژه‌های مختلف استفاده می‌شوند.</p>
<p>بعضی از این گرانیت‌ها می‌توانند به صورت اسلب نیز فرآوری شوند.</p>
<hr>
<h2>اسلب گرانیت خرمدره</h2>
<p>خرمدره معمولاً با زمینه خاکستری و دانه‌بندی مشخص شناخته می‌شود.</p>
