<p>گرانیت‌های نطنز نیز بسته به نوع و سورت می‌توانند برای پروژه‌های مختلف استفاده شوند.</p>
<p>در اسلب بهتر است چند قطعه کنار هم دیده شوند تا تفاوت سورت مشخص شود.</p>
