<hr>
<h2>اسلب گرانیت یا سنگ چینی؟</h2>
<p>اگر طراحی:</p>
<ul>
<li>سفید</li>
<li>روشن</li>
<li>رگه‌دار</li>
</ul>
<p>می‌خواهید، بعضی سنگ‌های چینی گزینه جذابی هستند.</p>
<p>اگر مقاومت سایشی و سختی اهمیت بیشتری دارد، گرانیت بسیار جدی است.</p>
<hr>
<h2>تایل بهتر است یا اسلب؟</h2>
<h3>اسلب را انتخاب کنید اگر:</h3>
<ul>
<li>بند کم می‌خواهید</li>
<li>کانتر دارید</li>
<li>جزیره دارید</li>
<li>دیوار شاخص دارید</li>
<li>ظاهر لوکس مهم است</li>
</ul>
<h4>تایل را انتخاب کنید اگر:</h4>
<ul>
<li>پروژه کف متراژ بالا است</li>
<li>هزینه مهم‌تر است</li>
<li>ابعاد استاندارد کافی است</li>
<li>حمل ساده‌تر می‌خواهید</li>
</ul>
<hr>
<h2>اسلب گرانیت برای پروژه لوکس</h2>
<p>در پروژه لوکس، ارزش اصلی اسلب فقط جنس سنگ نیست.</p>
<p>بلکه:</p>
<ul>
