<p>در بسیاری از پروژه‌ها، بله.</p>
<p>یکی از اصلی‌ترین ویژگی‌های گرانیت، <strong>مقاومت سایشی مناسب</strong> آن است.</p>
<p>کف ساختمان هر روز با ذرات ریز:</p>
<ul>
<li>خاک</li>
<li>شن</li>
<li>گردوغبار</li>
</ul>
<p>که زیر کفش قرار دارند در تماس است.</p>
<p>این ذرات می‌توانند مانند یک ماده ساینده عمل کنند و در طول زمان سطح بعضی سنگ‌ها را کدر کنند.</p>
<p>گرانیت به دلیل سختی بیشتر معمولاً در برابر چنین شرایطی عملکرد مناسبی دارد.</p>
<p>به همین دلیل برای کف:</p>
<ul>
