<li>مجتمع تجاری</li>
<li>ساختمان اداری</li>
<li>بانک</li>
<li>لابی پرتردد</li>
<li>راهرو</li>
<li>ورودی</li>
</ul>
<p>زیاد مورد استفاده قرار می‌گیرد.</p>
