<hr>
<h2>مهم‌ترین مزایای گرانیت برای کف</h2>
<h3>1. مقاومت سایشی بالا</h3>
<p>این شاید مهم‌ترین مزیت گرانیت برای کف باشد.</p>
<p>در فضای پرتردد، سنگ باید بتواند در برابر عبور مداوم افراد ظاهر خود را حفظ کند.</p>
<p>گرانیت‌های مناسب کف معمولاً نسبت به بسیاری از سنگ‌های نرم‌تر عملکرد بهتری در برابر سایش دارند.</p>
<hr>
<h3>2. مقاومت فشاری مناسب</h3>
<p>کف دائماً تحت وزن قرار دارد.</p>
<p>وزن:</p>
<ul>
<li>افراد</li>
<li>مبلمان</li>
<li>تجهیزات</li>
<li>در بعضی فضاها خودرو</li>
</ul>
<p>باید به زیرسازی منتقل شود.</p>
<p>گرانیت معمولاً ساختار متراکم و مقاومت فشاری مناسبی دارد.</p>
<p>البته مقاومت نهایی کف فقط به خود سنگ بستگی ندارد.</p>
<p><strong>زیرسازی و نصب صحیح نیز بسیار مهم هستند.</strong></p>
<hr>
<h3>3. جذب آب پایین در بسیاری از گرانیت‌ها</h3>
<p>یکی دیگر از مزایای بسیاری از گرانیت‌ها، جذب آب نسبتاً پایین آنهاست.</p>
<p>این ویژگی در محیط‌هایی مانند:</p>
<ul>
<li>آشپزخانه</li>
<li>ورودی</li>
<li>کف محوطه</li>
<li>فضای خارجی</li>
</ul>
<p>اهمیت بیشتری دارد.</p>
