<p>گرانیت یکی از سنگ‌های آذرین طبیعی است که معمولاً ساختاری متراکم و سخت دارد.</p>
<p>بسیاری از گرانیت‌ها به دلیل:</p>
<ul>
<li>مقاومت سایشی بالا</li>
<li>مقاومت فشاری مناسب</li>
<li>جذب آب نسبتاً پایین</li>
<li>دوام در شرایط محیطی</li>
