<hr>
<h2>آیا گرانیت برای نمای ساختمان مناسب است؟</h2>
<p>در بسیاری از پروژه‌ها، بله.</p>
<p>اما گرانیت را نمی‌توان مثل هر سنگ دیگری روی نما اجرا کرد و انتظار داشت صرفاً به دلیل مقاومت بالای سنگ، نتیجه ایمن باشد.</p>
<p>دو موضوع باید از هم جدا شوند:</p>
<h3>مقاومت خود سنگ</h3>
<p>گرانیت از این نظر می‌تواند بسیار مناسب باشد.</p>
<h3>نحوه اتصال سنگ به ساختمان</h3>
<p>اینجا معمولاً حساسیت اصلی شروع می‌شود.</p>
<p>گرانیت متراکم است و بسیاری از نمونه‌های آن سطح پشت کم‌جذب‌تری نسبت به سنگ‌هایی مانند تراورتن دارند.</p>
<p>بنابراین در نصب نما نباید فقط به <strong>چسبندگی ملات به پشت سنگ</strong> تکیه کرد.</p>
<hr>
<h2>مزایای سنگ گرانیت برای نما</h2>
<p>گرانیت اگر درست انتخاب و اجرا شود، مزایای مهمی دارد.</p>
<hr>
<h3>1. مقاومت مناسب در برابر شرایط جوی</h3>
<p>نمای ساختمان مستقیماً با محیط بیرون در تماس است.</p>
<p>سنگ باید در برابر:</p>
<ul>
<li>باران</li>
<li>رطوبت</li>
<li>تابش خورشید</li>
<li>آلودگی</li>
<li>تغییرات دما</li>
<li>باد</li>
</ul>
<p>عملکرد مناسبی داشته باشد.</p>
<p>بسیاری از گرانیت‌های متراکم در چنین شرایطی دوام خوبی دارند.</p>
<hr>
<h3>2. جذب آب پایین در بسیاری از گرانیت‌ها</h3>
<p>جذب آب پایین در نمای خارجی می‌تواند یک مزیت باشد.</p>
<p>زیرا نفوذ کمتر آب به خود سنگ می‌تواند احتمال بعضی آسیب‌های ناشی از رطوبت را کاهش دهد.</p>
<p>البته میزان جذب آب بین همه گرانیت‌ها یکسان نیست و باید مشخصات همان سنگ بررسی شود.</p>
<hr>
<h3>3. مقاومت سایشی بالا</h3>
<p>در نمای قسمت‌های پایین ساختمان، ورودی‌ها یا محیط‌های شهری، سطح ممکن است در معرض:</p>
<ul>
<li>گردوغبار</li>
<li>شست‌وشو</li>
<li>تماس</li>
<li>آلودگی</li>
</ul>
<p>باشد.</p>
<p>گرانیت معمولاً از نظر سایش عملکرد مناسبی دارد.</p>
<hr>
<h3>4. دوام طولانی</h3>
<p>یکی از دلایل استفاده از گرانیت در پروژه‌های عمومی و شهری، دوام بالای آن است.</p>
<p>اگر:</p>
<ul>
<li>سنگ مناسب باشد</li>
<li>ضخامت صحیح انتخاب شود</li>
<li>اتصال اصولی باشد</li>
<li>اجرای نما درست انجام شود</li>
</ul>
<p>می‌تواند طول عمر بالایی داشته باشد.</p>
<hr>
<h3>5. تنوع رنگ</h3>
<p>گرانیت فقط خاکستری نیست.</p>
<p>در نما می‌توان از انواع:</p>
<ul>
<li>خاکستری</li>
<li>مشکی</li>
<li>قرمز</li>
<li>صورتی</li>
<li>سبز</li>
<li>روشن</li>
</ul>
<p>استفاده کرد.</p>
<p>به همین دلیل در معماری مدرن می‌توان از گرانیت برای ایجاد:</p>
<ul>
<li>حجم‌های تیره</li>
<li>قاب‌های ورودی</li>
<li>طبقه همکف</li>
<li>ستون</li>
<li>بخش شاخص نما</li>
</ul>
<p>استفاده کرد.</p>
<hr>
<h2>معایب سنگ گرانیت برای نما</h2>
<p>مزایای گرانیت نباید باعث شود محدودیت‌های آن نادیده گرفته شوند.</p>
<hr>
<h3>1. وزن نسبتاً زیاد</h3>
<p>گرانیت سنگ متراکمی است و وزن قابل توجهی دارد.</p>
<p>این موضوع با افزایش:</p>
<ul>
<li>ابعاد</li>
<li>ضخامت</li>
<li>ارتفاع نصب</li>
</ul>
<p>اهمیت بیشتری پیدا می‌کند.</p>
<p>در نما باید بار واردشده به:</p>
<ul>
<li>دیوار</li>
<li>زیرسازی</li>
<li>اتصالات</li>
<li>سازه</li>
</ul>
<p>در نظر گرفته شود.</p>
<hr>
<h2>2. چسبندگی کمتر به ملات در بعضی شرایط</h2>
<p>این یکی از مهم‌ترین موضوعات اجرای گرانیت در نماست.</p>
<p>سنگ‌های متخلخل‌تر می‌توانند درگیری بیشتری با ملات ایجاد کنند.</p>
<p>اما بسیاری از گرانیت‌ها:</p>
<ul>
<li>جذب آب پایین</li>
<li>پشت نسبتاً صاف</li>
<li>تراکم بالا</li>
</ul>
<p>دارند.</p>
<p>در نتیجه اتکا به ملات بدون مهار مناسب می‌تواند ریسک جداشدن سنگ را افزایش دهد.</p>
<hr>
<h2>3. اجرای سنگین‌تر</h2>
<p>برش، سوراخ‌کاری و نصب گرانیت معمولاً نسبت به بعضی سنگ‌های نرم‌تر دشوارتر است.</p>
<p>این مسئله:</p>
<ul>
<li>زمان اجرا</li>
<li>ابزار</li>
<li>هزینه</li>
<li>مهارت مجری</li>
</ul>
<p>را تحت تأثیر قرار می‌دهد.</p>
<hr>
<h2>4. محدودیت در بعضی طراحی‌های کلاسیک</h2>
<p>اگر نما دارای:</p>
<ul>
<li>ابزار زیاد</li>
<li>حجاری</li>
<li>سرستون</li>
<li>جزئیات پیچیده</li>
</ul>
<p>باشد، بعضی سنگ‌های نرم‌تر ممکن است اجرای ساده‌تری داشته باشند.</p>
<p>گرانیت بیشتر در طراحی‌هایی که:</p>
<ul>
<li>ساده</li>
<li>هندسی</li>
<li>مدرن</li>
<li>مینیمال</li>
</ul>
<p>هستند جذاب است.</p>
