<p>گرانیت‌های خاکستری، مشکی و بعضی رنگ‌های تیره در طراحی مدرن محبوب‌اند، اما انتخاب نهایی باید با اقلیم و معماری پروژه هماهنگ باشد.</p>
<hr>
