<hr>
<h2>فرآوری سنگ گرانیت چیست؟</h2>
<p>بعد از اینکه گرانیت از معدن استخراج و به اسلب یا تایل تبدیل شد، سطح آن معمولاً به همان شکل خام باقی نمی‌ماند.</p>
