<li>بافت ایجاد شود</li>
<li>لغزندگی کاهش پیدا کند</li>
<li>رنگ سنگ واضح‌تر شود</li>
<li>سطح برای کاربرد مشخص آماده شود</li>
</ul>
<p>به مجموعه این عملیات، <strong>فرآوری سطح سنگ</strong> گفته می‌شود.</p>
<p>اگر ابتدا می‌خواهید با خود گرانیت، انواع آن و کاربردهای اصلی آشنا شوید، مقاله جامع گرانیت را ببینید.</p>
<p><a href="/fa/blogs/everything-about-granite-stone">سنگ گرانیت چیست؟ انواع، کاربردها و راهنمای خرید</a></p>
