<h2>چرا نوع فرآوری گرانیت مهم است؟</h2>
<p>فرض کنید یک گرانیت خاکستری دارید.</p>
<p>همان سنگ اگر:</p>
<h3>صیقلی شود</h3>
<p>سطح آن براق‌تر و رنگ آن عمیق‌تر دیده می‌شود.</p>
