<p>در این فرآیند سطح سنگ در معرض حرارت شدید و کنترل‌شده قرار می‌گیرد.</p>
<p>اختلاف رفتار کانی‌های موجود در گرانیت باعث می‌شود سطح سنگ کمی باز و زبر شود.</p>
<p>نتیجه:</p>
