<h2>تفاوت اصلی گرانیت و مرمریت چیست؟</h2>
<p>قبل از مقایسه کاربردها باید یک تفاوت بنیادی را بدانیم.</p>
<p><strong>گرانیت و مرمریت از نظر زمین‌شناسی دو خانواده متفاوت هستند.</strong></p>
<p>گرانیت معمولاً یک سنگ آذرین است که ساختاری بلوری و متراکم دارد.</p>
<p>مرمریت در بازار سنگ ایران عمدتاً به گروهی از سنگ‌های کربناته گفته می‌شود که قابلیت ساب و استفاده گسترده در فضای داخلی دارند.</p>
<p>همین تفاوت ساختاری باعث می‌شود رفتار این دو سنگ نیز یکسان نباشد.</p>
