<ul>
<li>سایش</li>
<li>ضربه‌های معمول</li>
<li>کف پرتردد</li>
<li>راه‌پله عمومی</li>
</ul>
<p>اهمیت دارد.</p>
<p>گرانیت معمولاً سخت‌تر از مرمریت است و در محیط‌های پرتردد می‌تواند دوام بسیار خوبی داشته باشد.</p>
<hr>
<h2>آیا این یعنی مرمریت ضعیف است؟</h2>
