<p>اما باید نوع مناسبی انتخاب شود.</p>
<p>مثلاً یک مرمریت سالم، متراکم و مناسب کف می‌تواند سال‌ها عملکرد خوبی داشته باشد.</p>
<p>مشکل زمانی ایجاد می‌شود که فقط براساس رنگ و ظاهر، سنگی برای کاربردی انتخاب شود که از نظر فنی مناسب نیست.</p>
