<h2>آیا گرانیت به‌صرفه است؟</h2>
<p>برای بعضی کاربردها، بسیار.</p>
<p>مثلاً در:</p>
<ul>
<li>کف پرتردد</li>
<li>پله</li>
<li>فضای عمومی</li>
</ul>
<p>دوام بالای گرانیت می‌تواند باعث شود هزینه اولیه در طول عمر پروژه منطقی باشد.</p>
<hr>
<h2>قیمت خرید مهم‌تر است یا هزینه چرخه عمر؟</h2>
<p>در پروژه حرفه‌ای بهتر است هر دو دیده شوند.</p>
<p>سنگی که:</p>
<p><strong>10 درصد ارزان‌تر</strong></p>
<p>است ولی نیاز به تعویض یا تعمیر بیشتری دارد، لزوماً گزینه اقتصادی‌تری نیست.</p>
<hr>
<h2>اشتباه اول هنگام خرید گرانیت: مقایسه فقط قیمت متر</h2>
<p>شاید دو محصول اصلاً مشخصات یکسانی نداشته باشند.</p>
<hr>
<h2>اشتباه دوم: توجه نکردن به ضخامت</h2>
<p>یک سنگ نازک‌تر طبیعتاً می‌تواند ارزان‌تر باشد.</p>
<hr>
<h2>اشتباه سوم: نادیده گرفتن سورت</h2>
<p>قیمت پایین‌تر ممکن است مربوط به سورت متفاوت باشد.</p>
