<li>قیمت منطقی داشته باشد</li>
</ul>
<hr>
<h2>برای کاهش هزینه پروژه چه کار کنیم؟</h2>
<h3>ابعاد استانداردتر انتخاب کنید</h3>
<p>پرت و هزینه برش کمتر می‌شود.</p>
<h4>سورت متناسب بخرید</h4>
<p>برای محوطه لازم نیست بالاترین سورت را انتخاب کنید.</p>
<h4>فرآوری متناسب انتخاب کنید</h4>
<p>پرداخت اضافی که کاربردی نیست هزینه ایجاد می‌کند.</p>
<h4>کل پروژه را قبل از سفارش طراحی کنید</h4>
<p>میزان پرت کمتر می‌شود.</p>
