<h2>بالاخره قیمت سنگ گرانیت چقدر است؟</h2>
<p>برای این سؤال نمی‌توان یک عدد ثابت و قابل اعتماد برای تمام گرانیت‌ها ارائه کرد.</p>
<p>چون ممکن است دو گرانیت از نظر قیمت چند برابر تفاوت داشته باشند.</p>
<p>مهم‌تر از دانستن یک عدد عمومی این است که بدانید:</p>
<blockquote>
<p><strong>چه چیزی دارید مقایسه می‌کنید.</strong></p>
