<p>اگر:</p>
<ul>
<li>معدن</li>
<li>سورت</li>
<li>ابعاد</li>
<li>ضخامت</li>
<li>فرآوری</li>
<li>مقدار</li>
</ul>
<p>مشخص نباشند، قیمت‌ها قابل مقایسه نیستند.</p>
<p>بنابراین بهترین روش خرید این است:</p>
<ol>
<li>کاربرد را مشخص کنید.</li>
<li>مشخصات فنی موردنیاز را تعیین کنید.</li>
<li>چند محصول مناسب را انتخاب کنید.</li>
<li>قیمت آنها را با مشخصات یکسان مقایسه کنید.</li>
<li>هزینه حمل، پرت و اجرا را هم اضافه کنید.</li>
</ol>
<p>این روش احتمال خرید اشتباه را بسیار کمتر می‌کند.</p>
