<h2>جمع‌بندی</h2>
<p><strong>قیمت سنگ گرانیت</strong> فقط براساس نام سنگ تعیین نمی‌شود.</p>
<p>مهم‌ترین عوامل عبارت‌اند از:</p>
<ul>
