<li>سنگ چینی</li>
<li>تراورتن</li>
</ul>
<p>بیشتر بررسی می‌شوند.</p>
<p>هرکدام مزایا و محدودیت‌های خودشان را دارند.</p>
<p>در این راهنما بررسی می‌کنیم:</p>
<ul>
<li>بهترین سنگ برای پله ساختمان چیست؟</li>
<li>گرانیت برای پله بهتر است یا مرمریت؟</li>
<li>سنگ چینی برای راه‌پله مناسب است؟</li>
<li>تراورتن را می‌توان برای پله استفاده کرد؟</li>
<li>برای پله داخلی و خارجی چه سنگی مناسب‌تر است؟</li>
<li>ضخامت و نوع فرآوری سنگ پله باید چگونه باشد؟</li>
<li>هنگام خرید سنگ پله باید به چه نکاتی توجه کنیم؟</li>
</ul>
<hr>
<h2>سنگ پله باید چه ویژگی‌هایی داشته باشد؟</h2>
<p>پله از نظر فنی با بسیاری از بخش‌های دیگر ساختمان متفاوت است.</p>
<p>هر کف‌پله دارای یک <strong>لبه آزاد</strong> است که بیشتر از سایر قسمت‌های سنگ در معرض ضربه قرار دارد.</p>
<p>بنابراین سنگ مناسب راه‌پله باید چند ویژگی مهم داشته باشد.</p>
<hr>
<h3>1. مقاومت سایشی مناسب</h3>
<p>هر بار که فردی از پله بالا یا پایین می‌رود، سطح سنگ تحت سایش قرار می‌گیرد.</p>
<p>در ساختمان‌هایی مانند:</p>
<ul>
<li>مجتمع تجاری</li>
<li>اداره</li>
<li>هتل</li>
<li>ساختمان عمومی</li>
<li>آپارتمان پرتردد</li>
</ul>
<p>این سایش بسیار بیشتر است.</p>
<p>اگر سنگ مقاومت کافی نداشته باشد، بخش وسط کف‌پله به مرور می‌تواند نسبت به اطراف:</p>
<ul>
<li>کدرتر</li>
<li>ساییده‌تر</li>
<li>مات‌تر</li>
</ul>
<p>شود.</p>
<hr>
<h2>2. سلامت سنگ</h2>
<p>در سنگ پله وجود ترک اهمیت بیشتری از دیوار دارد.</p>
<p>چون قطعه پله علاوه بر فشار، در قسمت لبه نیز تنش بیشتری تحمل می‌کند.</p>
<p>هنگام خرید باید به:</p>
<ul>
<li>ترک باز</li>
<li>شکستگی</li>
<li>رگه ضعیف</li>
<li>لب‌پریدگی</li>
<li>نقاط ترمیم‌شده</li>
</ul>
<p>توجه شود.</p>
<p>هر خط طبیعی روی سنگ الزاماً ترک نیست.</p>
<p><a href="/fa/blogs/crack-or-vein-in-natural-stone">تفاوت ترک و رگه طبیعی سنگ</a></p>
<hr>
<h2>3. ضخامت مناسب</h2>
<p>ضخامت کف‌پله باید متناسب با:</p>
<ul>
<li>طول پله</li>
<li>عرض</li>
<li>میزان بیرون‌زدگی</li>
<li>نوع سنگ</li>
<li>زیرسازی</li>
<li>میزان تردد</li>
</ul>
<p>انتخاب شود.</p>
<p>سنگی که برای دیوار با ضخامت کمتر مناسب است، الزاماً برای کف پله انتخاب درستی نیست.</p>
<hr>
<h2>4. مقاومت لبه</h2>
<p>لبه پله یکی از حساس‌ترین نقاط است.</p>
<p>اگر سنگ:</p>
<ul>
<li>ضعیف باشد</li>
<li>رگه نامناسب داشته باشد</li>
<li>ابزار لبه بیش از حد ظریف باشد</li>
</ul>
<p>احتمال لب‌پر شدن بیشتر می‌شود.</p>
<hr>
<h2>5. سطح غیرلغزنده در محل مناسب</h2>
<p>در راه‌پله داخلی خشک می‌توان از سطح صیقلی استفاده کرد.</p>
<p>اما در:</p>
<ul>
<li>پله بیرونی</li>
<li>ورودی</li>
<li>فضای باران‌خور</li>
<li>محیط مرطوب</li>
</ul>
<p>سطح بسیار براق می‌تواند خطر لغزش ایجاد کند.</p>
<hr>
<h2>6. قابلیت تأمین قطعات یکدست</h2>
<p>راه‌پله معمولاً تعداد زیادی قطعه پشت سر هم دارد.</p>
<p>اگر رنگ هر پله با پله بعدی متفاوت باشد، اختلاف سورت به‌وضوح دیده می‌شود.</p>
<p>بنابراین برای پروژه‌های بزرگ باید کل بار همزمان سورت شود.</p>
